import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"Containerd + Kata","description":"","frontmatter":{},"headers":[],"relativePath":"installation/kata-containerd.md","filePath":"installation/kata-containerd.md","lastUpdated":1780895553000}'),n={name:"installation/kata-containerd.md"};function o(h,s,l,r,p,d){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="containerd-kata" tabindex="-1">Containerd + Kata <a class="header-anchor" href="#containerd-kata" aria-label="Permalink to &quot;Containerd + Kata&quot;">​</a></h1><p>Memoh can run bot workspaces with Kata Containers through the <code>containerd</code> workspace backend. This keeps the normal Memoh workspace lifecycle while asking containerd to start each workspace with <code>io.containerd.kata.v2</code>.</p><p>Use this setup when you want VM-backed workspace isolation on a Linux/KVM host. It is not available on macOS or Docker Desktop hosts.</p><h2 id="when-to-use-it" tabindex="-1">When to Use It <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to Use It&quot;">​</a></h2><ul><li>You deploy Memoh on a Linux server with KVM.</li><li>You want each bot workspace to run behind a lightweight VM boundary.</li><li>You still want the Memoh workspace APIs, snapshots, files, commands, and UI controls to behave like the normal <code>containerd</code> backend.</li></ul><p>Kata is still managed through containerd snapshots in Memoh. CPU and memory limits are hard limits. Storage is currently saved and reported as a soft limit until VM disk quota or block-device quota support is added.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Linux host with <code>/dev/kvm</code>.</li><li>Nested virtualization if the host itself is a VM.</li><li>Docker and Docker Compose v2.</li><li>Kata Containers installed on the host.</li><li>A host Kata runtime such as <code>io.containerd.kata.v2</code>.</li></ul><p>The default compose overlay expects these host paths:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_KATA_SHIM_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/opt/kata/bin/containerd-shim-kata-v2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_KATA_CONFIG_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/etc/kata-containers</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_KATA_SHARE_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/usr/share/kata-containers</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_KATA_OPT_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/opt/kata</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MEMOH_KATA_SYSLOG_SOCKET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/run/systemd/journal/dev-log</span></span></code></pre></div><p>If your Kata installation uses different paths, export the matching variables before starting Memoh.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>In <code>config.toml</code>, keep the workspace backend as <code>containerd</code> and set the containerd runtime type:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">container</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backend = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;containerd&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">containerd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">runtime_type = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;io.containerd.kata.v2&quot;</span></span></code></pre></div><p><code>container_backend</code> will still report <code>containerd</code>. To confirm that a bot workspace is actually using Kata, check the workspace runtime value: <code>runtime_backend = &quot;io.containerd.kata.v2&quot;</code>.</p><p>You can also inspect the container directly from the Memoh server environment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ctr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> containers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> workspace-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bot-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>The expected container runtime name is <code>io.containerd.kata.v2</code>.</p><h2 id="compose-overlay" tabindex="-1">Compose Overlay <a class="header-anchor" href="#compose-overlay" aria-label="Permalink to &quot;Compose Overlay&quot;">​</a></h2><p>Start Memoh with the Kata compose overlay:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.kata.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>The overlay mounts the host KVM device, Kata shim, Kata configuration, and Kata runtime assets into the Memoh server container.</p><p>The Dockerized Memoh server runs a nested containerd for bot workspaces. The Kata compose overlay therefore uses <code>cgroup: host</code> and <code>shm_size: 1gb</code> on the server service. The host cgroup namespace lets the nested Kata runtime create sandbox cgroup controllers, and the larger shared-memory segment avoids QEMU/KVM boot failures caused by Docker&#39;s small default <code>/dev/shm</code>.</p><p>The syslog socket is mounted into the server container as <code>/dev/log</code> so the Kata shim can initialize logging. On non-systemd hosts, set <code>MEMOH_KATA_SYSLOG_SOCKET</code> to the host syslog socket path.</p><h2 id="bridge-networking" tabindex="-1">Bridge Networking <a class="header-anchor" href="#bridge-networking" aria-label="Permalink to &quot;Bridge Networking&quot;">​</a></h2><p>Kata workspaces use the bridge TCP listener (<code>BRIDGE_TCP_ADDR=:9090</code>) instead of the Unix socket bridge used by normal containerd workspaces. A Unix socket can appear on the host through the Kata shared filesystem, but it is not a usable connection boundary across the guest VM.</p><p>Memoh routes Kata bridge traffic to the workspace CNI IP. Bridge gRPC dials also bypass HTTP proxy settings so server-level proxy variables do not intercept private workspace addresses.</p><h2 id="build-proxy" tabindex="-1">Build Proxy <a class="header-anchor" href="#build-proxy" aria-label="Permalink to &quot;Build Proxy&quot;">​</a></h2><p>If the Linux/KVM host needs a proxy while Docker builds images, set build proxy variables before starting or rebuilding the Kata compose stack:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MEMOH_KATA_BUILD_HTTP_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://172.17.0.1:7890</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MEMOH_KATA_BUILD_HTTPS_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://172.17.0.1:7890</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MEMOH_KATA_BUILD_NO_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">127.0.0.1,localhost</span></span></code></pre></div><p>Use a host address that is reachable from Docker build containers. On Linux, <code>localhost</code> inside a Dockerfile <code>RUN</code> step is the build container, not the host.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>After startup, create or recreate a bot workspace and check that the workspace runtime is <code>io.containerd.kata.v2</code>.</p><p>For a direct runtime smoke test, run a small container with the Kata runtime inside the server&#39;s containerd environment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ctr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --runtime</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> io.containerd.kata.v2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --snapshotter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> overlayfs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  docker.io/library/alpine:3.22</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  memoh-kata-smoke</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  /bin/sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;printf &quot;runtime-smoke-ok\\n&quot;&#39;</span></span></code></pre></div><p>If the direct smoke test passes but a bot workspace cannot start, check the server logs for Kata shim, cgroup, <code>/dev/log</code>, <code>/dev/kvm</code>, or bridge connection errors.</p>`,36)])])}const g=a(n,[["render",o]]);export{c as __pageData,g as default};
